fn ids<'a>(names:impl Iterator<Item=&'a str>,p:&mut Projection<'_,'_>)->Result<BTreeMap<&'a str,i64>,ValueError>{let mut result=BTreeMap::new();for(ordinal,name)in names.enumerate(){p.check_rows(ordinal+1)?;if result.insert(name,number(ordinal+1)?).is_some(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"duplicate BRep native entity identity"));}if ordinal%256==0{p.checkpoint()?;}}Ok(result)}
fn fk(names:&BTreeMap<&str,i64>,id:&str)->Result<i64,ValueError>{names.get(id).copied().ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"dangling BRep topology reference"))}
fn ring(rows:&BTreeMap<i64,SqliteRow<'_>>,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{for(n,row)in rows.values().enumerate(){let next=rows.get(&row.integer(10)?).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"dangling next coedge"))?;let prev=rows.get(&row.integer(11)?).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"dangling previous coedge"))?;if next.integer(11)?!=row.rowid||prev.integer(10)?!=row.rowid||next.integer(9)?!=row.integer(9)?||prev.integer(9)?!=row.integer(9)?{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"nonreciprocal or cross-loop BRep coedge ring"));}if n%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,n,0)?;}}Ok(())}
